    nautiloid:{questsCompanions:[entry('nautiloid-us-laezel-shadowheart','“我们”、莱埃泽尔与影心','沿主路依次处理三次相遇，并明确救援影心。','跳过救援舱会改变影心在海滩的起点。','Nautiloid')],merchantsStock:[],permanentBonuses:[],hiddenAreas:[entry('nautiloid-brain-jars','脑罐与舵室支路','在倒计时前检查可安全到达的侧室与容器。','不要为可选物件错过传送器倒计时。','Nautiloid')],campEvents:[]},
