    'overgrown-ruins':{questsCompanions:[entry('ruins-withers','唤醒维瑟斯','清理阴暗墓穴并开启最深处石棺。','未唤醒时他之后仍可能到营地，但会错过墓穴内容。','Explore_the_Ruins')],merchantsStock:[],permanentBonuses:[],hiddenAreas:[entry('ruins-trap-sarcophagus','陷阱石棺与灵魂钱币','拆除喷口、地板按钮与石棺机关后逐项搜取。','机关连锁会烧毁队伍并掩盖战利品。','Dank_Crypt')],campEvents:[entry('withers-arrival','维瑟斯抵达营地','完成墓穴后长休并与维瑟斯交谈。','营地服务需等他实际出现。','Withers')]},
