    'goblin-camp':{questsCompanions:[entry('camp-volo-halsin-liam','沃罗、哈尔辛与利亚姆','在全营敌对前依次救出并确认去向。','先杀首领可能让交易与和平救援更困难。','Goblin_Camp')],merchantsStock:[entry('camp-grat-roah','格拉特与罗亚月光窗口','敌对前完成装备采购和补给。','全营敌对或商人死亡会永久关闭第一章窗口。','Goblin_Camp')],permanentBonuses:[],hiddenAreas:[entry('sanctum-treasure-rooms','明萨拉房、拉格兹林宝库与蜘蛛坑','分别开启固定箱柜并标记逃生路线。','首领战后的敌对状态会增加搜取难度。','Shattered_Sanctum')],campEvents:[entry('volo-surgery-camp','沃罗手术','救出沃罗后在营地连续完成寄生虫对话。','手术不可逆且与同角色鬼婆眼部交易互斥。','Volo')]},
    'waukeens-rest-surface':{questsCompanions:[entry('waukeen-florrick-benryn-rugan','弗洛瑞克、本林与鲁根货物','触发火场后连续救援，再结算未开保险箱。','离区或长休会使火场人物死亡；货物开箱改变散塔林会结果。','Waukeen%27s_Rest')],merchantsStock:[entry('zhent-brem-stock','布雷姆与扎瑞斯奖励','按保险箱状态确认哈罗德和特殊库存。','开箱、背叛或敌对会失去对应奖励。','Find_the_Missing_Shipment')],permanentBonuses:[],hiddenAreas:[entry('zhent-hideout-lift','散塔林会地下藏身处与升降机','通过谷仓入口，标记北端幽暗地域升降机。','油路与炸药连锁会摧毁容器和商人。','Zhentarim_Hideout')],campEvents:[]},
