    'mountain-pass-monastery':{questsCompanions:[entry('mountain-esther-eagles-ceremonial','埃斯特、巨鹰与仪式武器','先决定蛋委托，再处理屋顶巢穴与四武器祭台。','山隘推进会结算部分地表任务；巨鹰敌对会改变取得方式。','Rosymorn_Monastery_Trail')],merchantsStock:[entry('mountain-esther-stock','埃斯特库存','在决定吉斯洋基蛋去向前购买关键装备。','交付或敌对后不能保证继续交易。','Lady_Esther')],permanentBonuses:[],hiddenAreas:[entry('monastery-lathander-crest','彩窗祭台与黎明主宰者徽记','把四件仪式武器放到正确祭台并取出徽记。','强拿遗物会触发四回合毁灭机关。','Dawnmaster%27s_Crest')],campEvents:[]},
    'creche-yllk':{questsCompanions:[entry('creche-laezel-egg-inquisitor','莱埃泽尔、吉斯洋基蛋与审判官','在中立阶段完成教室、孵化间和主线会面。','敌对后交易与部分对话会关闭。','Cr%C3%A8che_Y%27llek')],merchantsStock:[entry('creche-quartermaster-stock','军需官完整库存','在医务室与队长房推进前购买全部列名装备。','养育间敌对后无法保证补购。','A%27jak%27nir_Jeera')],permanentBonuses:[],hiddenAreas:[entry('creche-inquisitor-secret-chamber','审判官侧廊与洛山达密室','搜取固定装备后转动雕像进入密道。','直接强取洛山达之血会启动毁灭机关。','Secret_Chamber')],campEvents:[entry('creche-voss-camp-visit','沃斯营地来访','完成棱镜与莱埃泽尔对话后，长休前保存。','来访条件依莱埃泽尔状态与养育间结果。','The_Githyanki_Warrior')]}
